import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·17","description":"易小帖 - 卷二·17","frontmatter":{"title":"卷二·17","description":"易小帖 - 卷二·17"},"headers":[],"relativePath":"zh/classics/yixiaotie/057.md","filePath":"zh/classics/yixiaotie/057.md"}'),o={name:"zh/classics/yixiaotie/057.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·17",tabindex:"-1"},[r("卷二·17 "),e("a",{class:"header-anchor",href:"#卷二·17","aria-label":"Permalink to “卷二·17”"},"​")],-1),e("p",null,"舊儒論互卦以京焦馬鄭諸說為據，此師承之說也。後有據及《大傳》者，如二四同功為下互，三五同功為上互類，亦既明曉。奈俗學鄙陋，終執王韓之說，謂無互卦。予作《仲氏易》時已引本易爻詞及春秋傳斷詞，確示之矣。後作《推易始末》又悟伏羲卦名，早及互卦，如乾兌為履，履者禮也，乾兌西金之卦，於行屬義焉，有所謂禮者。既視其畫則上互為巽，下互為離，離巽於南方為火，於行為禮，則在卦名已有之。又泰之六五有「帝乙歸妹」之文，泰為坤乾並，非震兌，安得有兄妹之稱，第以三五上互震。二四下互兌，故及之。則演卦立名，且有旁及互體者，況其他耶。予同館喬侍讀作《易俟》一書，極駁互卦，且曰折衷，孔子予不知其何所解，惜不作一札詰之。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
